action.code:
if (internal_key.size() < 8) {
  return false;
}

const char* data = internal_key.data();
const char* end = data + internal_key.size();
const uint64_t num = DecodeFixed64(end - 8);
user_key->assign(data, end - 8 - data);
*sequence = num >> 8;
*type = static_cast<uint8_t>(num & 0xff);
return true;

